<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from '../../api/client'
import ReviewFinding from './ReviewFinding.vue'
import { reportLabels, reviewLabels, tone } from './presentation'
const route = useRoute(), project = ref(null), candidate = ref(null), report = ref(null), error = ref(''), loading = ref(true)
const content = computed(() => report.value?.content || {})
async function load() {
  loading.value = true; error.value = ''
  try {
    const [p, candidates] = await Promise.all([api(`/projects/${route.params.id}`), api(`/projects/${route.params.id}/candidates`)])
    const match = candidates.find(c => c.session_id === route.params.sessionId)
    if (!match) throw new Error('이 프로젝트에 속한 지원자의 리포트를 찾을 수 없습니다.')
    project.value = p; candidate.value = match
    report.value = await api(`/reports/${route.params.sessionId}`)
  } catch (e) { error.value = e.message } finally { loading.value = false }
}
onMounted(load)
</script>
<template><main class="page report-page"><div class="back"><RouterLink to="/projects">평가 프로젝트</RouterLink> / <RouterLink :to="`/projects/${route.params.id}`">지원자 관리</RouterLink> / 개인별 리포트</div><div class="page-heading"><div><h1>{{ candidate ? `${candidate.alias}의 업무 리포트` : '개인별 리포트' }}</h1><p v-if="project" class="muted">{{ project.title }} · {{ project.scenario_title }}</p></div><button class="secondary" :disabled="loading" @click="load">새로고침</button></div><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="loading" class="muted" role="status">리포트를 불러오고 있습니다…</p><template v-if="report"><p class="report-status"><span class="badge" :class="tone(report.status)">{{ reportLabels[report.status] || report.status }}</span></p><p v-if="report.status === 'not_configured'" class="notice">관찰 기준이 설정되지 않은 실행입니다. 역량 분석 결과를 생성하지 않았습니다.</p><p v-else-if="report.status !== 'ready'" class="notice" role="status">{{ reportLabels[report.status] || report.status }} · 새로고침으로 상태를 확인할 수 있습니다.</p><p v-if="content.message" class="notice">{{ content.message }}</p><p v-if="content.ai_review && content.ai_review.status !== 'ready'" class="notice">{{ content.ai_review.message }}</p><div class="report-layout"><nav class="report-nav" aria-label="리포트 내 이동"><a v-if="content.final_review?.summary" href="#report-overview">AI 종합 의견</a><a v-if="content.final_review" href="#report-deliverable">최종 결과물 검토</a><a v-if="content.items?.length" href="#report-competencies">역량별 평가</a><p class="report-help">AI 의견과 원문 근거를 함께 확인해 주세요.</p></nav><div class="report-body"><section v-if="content.final_review?.summary" id="report-overview" class="card report-overview"><span class="eyebrow">ASSESSMENT OVERVIEW</span><h2>AI 종합 의견</h2><ReviewFinding :finding="content.final_review.summary" :sources="content.review_sources" /></section><section v-if="content.final_review" id="report-deliverable" class="card"><div class="review-heading"><h2>최종 결과물 검토</h2><span class="muted small">시나리오 기준 {{ content.final_review.criteria.length }}개</span></div><p class="muted review-caption">최종 제출물과 제공된 자료를 시나리오 기준에 따라 대조한 AI 검토 의견입니다.</p><article v-for="(criterion,index) in content.final_review.criteria" :key="criterion.id" class="deliverable-criterion"><div class="review-heading"><h3><span class="criterion-number">{{ String(index + 1).padStart(2,'0') }}</span>{{ criterion.title }}</h3><span class="badge" :class="tone(criterion.status)">{{ reviewLabels[criterion.status] || criterion.status }}</span></div><ReviewFinding v-if="criterion.finding" :finding="criterion.finding" :sources="content.review_sources" /><p v-else class="muted">{{ criterion.message }}</p><details class="criterion-definition"><summary>검토 기준</summary><p>{{ criterion.description }}</p></details></article><details class="criterion-definition"><summary>기준 버전 확인</summary>{{ content.final_review.criteria_version }}</details></section><section v-if="content.items?.length" id="report-competencies" class="card"><h2>역량별 평가</h2><p class="muted review-caption">관찰된 행동과 AI 해석을 구분해 확인합니다.</p><article v-for="item in content.items" :key="item.competency_id" class="report-item"><div class="review-heading"><h3>{{ item.name }}</h3><span class="muted small">연결 근거 {{ item.evidence?.length || 0 }}개</span></div><section v-if="item.ai_evaluation" class="competency-ai-review"><strong>AI 평가</strong><template v-if="item.ai_evaluation.status === 'ready'"><ReviewFinding :finding="item.ai_evaluation.summary" :sources="content.review_sources" /><div class="review-insights"><div v-if="item.ai_evaluation.strength"><h4>확인된 강점</h4><ReviewFinding :finding="item.ai_evaluation.strength" :sources="content.review_sources" /></div><div v-if="item.ai_evaluation.improvement"><h4>보완할 점</h4><ReviewFinding :finding="item.ai_evaluation.improvement" :sources="content.review_sources" /></div></div></template><p v-else class="muted">{{ item.ai_evaluation.message }}</p></section><p v-if="!item.ai_evaluation" class="muted">{{ item.summary }}</p><details class="behavior-details"><summary>관찰 상황과 활동 기록 펼치기</summary><p v-if="item.ai_evaluation" class="muted">{{ item.summary }}</p><div v-for="s in item.situations || []" :key="s.rule_id" class="notice"><strong>{{ s.label }}</strong><p>{{ s.content || '해당 상황이 제공되기 전에 응시가 종료되었습니다.' }}</p><small>{{ s.status === 'recorded' ? '관련 시점의 활동 기록 있음 · 내용 검토 필요' : s.status === 'not_provided' ? '관찰 기회 미제공' : '설정 시간 범위 내 연결 기록 없음' }}</small></div><blockquote v-for="e in item.evidence || []" :key="e.rule_id + e.id"><small>경과 {{ Math.floor(e.elapsed / 60) }}분 · 근거 {{ e.id }}</small><p>{{ e.quote }}</p><small>{{ e.fact }}</small></blockquote></details></article></section><p v-if="content.activity_count !== undefined" class="muted small">저장된 활동 기록 {{ content.activity_count }}개 · AI 의견은 근거와 함께 검토하며, 최종 판단은 담당자가 합니다.</p></div></div></template></main></template>
